INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Section 501(h) expenditure test election vs. substantial part test
(3, 'Tax-Exempt Organizations', 'Hope Alliance, a 501(c)(3) public charity with exempt purpose expenditures of $800,000, elects the Section 501(h) expenditure test. It spends $120,000 on direct lobbying and $30,000 on grassroots lobbying. The nontaxable lobbying ceiling is $140,000 (20% of first $500,000 plus 15% of next $300,000), and the grassroots ceiling is 25% of that ($35,000). Evaluate whether Hope Alliance has exceeded its lobbying limits under the expenditure test.', '["Hope Alliance is within both limits because $120,000 direct lobbying is under the $140,000 ceiling and $30,000 grassroots is under the $35,000 ceiling", "Hope Alliance has exceeded the direct lobbying limit but is within the grassroots limit", "Hope Alliance has exceeded both the direct lobbying and grassroots lobbying limits", "Hope Alliance has exceeded only the grassroots lobbying limit"]'::jsonb, 0, 'Under IRC Section 501(h), the expenditure test provides specific dollar thresholds rather than the vague "substantial part" standard. Direct lobbying of $120,000 is below the $140,000 ceiling, and grassroots lobbying of $30,000 is below the $35,000 ceiling (25% of $140,000). Unlike the substantial part test, the 501(h) election gives organizations a measurable safe harbor. Option C is wrong because neither limit was exceeded.', 'hard', 4),

-- Q2: hard / L4 — Controlled entity payments treated as UBIT
(3, 'Tax-Exempt Organizations', 'Riverside Health Foundation, a 501(c)(3), owns 85% of Riverside Medical Supplies, Inc., a taxable C corporation. The subsidiary pays the foundation $200,000 in annual rent for office space. An independent appraisal determines the fair market rent is $150,000. Analyze how Section 512(b)(13) treats this rental payment for UBIT purposes and determine the taxable amount.', '["The entire $200,000 is excluded from UBIT because rents from real property are always passive income", "Only rents exceeding the $1,000 specific deduction are included in UBIT", "The entire $200,000 is included in UBIT because Riverside Medical Supplies is a controlled entity", "The $50,000 excess above fair market value is included in UBIT as a controlled entity payment"]'::jsonb, 3, 'Under IRC Section 512(b)(13), rent, interest, or royalties from a controlled entity (80%+ ownership) are treated as UBIT to the extent they exceed fair market value. Since the foundation owns 85%, Riverside Medical Supplies is a controlled entity. The $50,000 excess ($200,000 paid minus $150,000 FMV) is included in UBIT. Option C is wrong because only the excess above FMV is taxable, not the entire payment.', 'hard', 4),

-- Q3: easy / L2 — Convenience exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Valley General Hospital, a 501(c)(3), operates a cafeteria on its premises that serves meals to patients, their families, and hospital staff. The cafeteria generated $180,000 in revenue during the year. How is the cafeteria income treated for UBIT purposes?', '["The income is subject to UBIT because operating a cafeteria is a trade or business", "The income is excluded from UBIT under the convenience exclusion because the cafeteria primarily serves patients and employees", "The income is subject to UBIT because the cafeteria charges market-rate prices", "The income is excluded only if all cafeteria workers are volunteers"]'::jsonb, 1, 'Under IRC Section 513(a)(2), a trade or business conducted primarily for the convenience of members, students, patients, or employees is excluded from UBIT. A hospital cafeteria serving patients, families, and staff qualifies for this convenience exclusion regardless of pricing. Option A is wrong because the convenience exclusion overrides the trade-or-business classification when the activity primarily serves the organization''s constituents.', 'easy', 2),

-- Q4: medium / L2 — Supporting organization under Section 509(a)(3)
(3, 'Tax-Exempt Organizations', 'Education First, Inc. is organized and operated exclusively to raise funds and provide administrative support for Lincoln University, a public charity. Education First does not receive broad public support but exists solely to benefit Lincoln University. Under which section does Education First qualify as a public charity rather than a private foundation?', '["Section 509(a)(1), because it supports an educational institution", "Section 509(a)(2), because it receives gross receipts from exempt functions", "Section 509(a)(3), because it is operated exclusively to support a public charity", "Section 509(a)(4), because it tests for public safety"]'::jsonb, 2, 'Under IRC Section 509(a)(3), an organization operated exclusively to support one or more public charities qualifies as a supporting organization and is classified as a public charity, even without broad public support. Education First exists solely to benefit Lincoln University, meeting this test. Option A is wrong because Section 509(a)(1) requires the organization itself to receive substantial public or governmental support, not merely support another charity.', 'medium', 2),

-- Q5: hard / L3 — Personal property rents mixed lease (10% threshold)
(3, 'Tax-Exempt Organizations', 'Heritage Arts Center, a 501(c)(3), leases a building to a commercial tenant under a single lease. The lease specifies annual rent of $100,000 for the building and $15,000 for furnishings and equipment inside the building. Apply the personal property rent rules to determine what portion of the total $115,000 rent is subject to UBIT.', '["The entire $115,000 is excluded because all rents under a single lease are treated as real property rents", "The $15,000 personal property rent is included in UBIT and the $100,000 real property rent is excluded, because the personal property exceeds the 10% incidental threshold", "The entire $115,000 is subject to UBIT because the lease includes both real and personal property", "Only $5,000 is subject to UBIT after applying the 10% threshold as a deduction"]'::jsonb, 1, 'Under IRC Section 512(b)(3) and Treas. Reg. Section 1.512(b)-1(c)(2)(ii), rents from real property are excluded from UBIT, but personal property rents are included unless incidental (less than 10% of total rent). Here, personal property rent ($15,000) is 13% of total rent ($115,000), exceeding the 10% threshold. Only the $15,000 personal property portion is subject to UBIT. Option A is wrong because personal property and real property rents are analyzed separately when the personal property exceeds the incidental threshold.', 'hard', 3),

-- Q6: medium / L2 — Form 990 Schedule J purpose
(3, 'Tax-Exempt Organizations', 'Civic Health Alliance, a large 501(c)(3) with $5 million in gross receipts, is preparing its annual Form 990. The organization''s accountant needs to report detailed compensation information for the executive director, chief financial officer, and board members. Which Form 990 schedule is used for this purpose?', '["Schedule A — Public Charity Status and Public Support", "Schedule B — Schedule of Contributors", "Schedule D — Supplemental Financial Statements", "Schedule J — Compensation Information"]'::jsonb, 3, 'Under IRC Section 6033, Form 990 Schedule J requires reporting of compensation information for officers, directors, trustees, key employees, and highest compensated employees, including total compensation, bonuses, and other benefits. Option A is wrong because Schedule A reports public charity classification and the public support test calculations, not individual compensation data.', 'medium', 2),

-- Q7: medium / L3 — Operational test failure (primarily non-exempt activities)
(3, 'Tax-Exempt Organizations', 'Bright Future Foundation, a 501(c)(3) educational charity, spends 70% of its budget operating a commercial printing business that serves paying customers. The remaining 30% funds scholarship programs for underprivileged students. The printing business has no educational component. Apply the operational test to determine whether Bright Future meets the requirements for maintaining exempt status.', '["Bright Future passes the operational test because 30% of activities further exempt purposes", "Bright Future fails the operational test because it is not operated primarily for exempt purposes", "Bright Future passes because the printing income funds scholarships", "Bright Future fails only if the printing business generates a profit"]'::jsonb, 1, 'Under IRC Section 501(c)(3), the operational test requires an organization to be operated primarily for exempt purposes. Spending 70% of the budget on a commercial printing business with no educational component means the organization is not primarily furthering exempt purposes. Option C reflects a common misconception — using income for exempt purposes does not make the income-producing activity itself substantially related to the exempt purpose.', 'medium', 3),

-- Q8: medium / L3 — Dissolution clause missing from governing documents
(3, 'Tax-Exempt Organizations', 'New Vision Charities, Inc. submits Form 1023 to apply for 501(c)(3) status. Its articles of incorporation state that the organization is formed exclusively for charitable purposes and prohibit private inurement. However, the articles do not address what happens to the organization''s assets if it dissolves. Apply the organizational test to determine the impact of this omission.', '["The application will be approved because the charitable purpose limitation satisfies the organizational test", "The omission has no effect because dissolution is governed by state law, not the organizational test", "The application will be denied because the articles lack a required dissolution clause", "The application will be approved if the organization later amends its articles after receiving its determination letter"]'::jsonb, 2, 'Under IRC Section 501(c)(3) and Treas. Reg. Section 1.501(c)(3)-1(b)(4), the organizational test requires that governing documents include a dissolution clause directing assets to another exempt organization or the government upon dissolution. Without this clause, the organization fails the organizational test regardless of its stated charitable purpose. Option A is wrong because limiting purposes to charitable activities alone is insufficient — the dissolution clause is a separate, mandatory requirement.', 'medium', 3),

-- Q9: medium / L3 — NOL deduction for UBIT limited to UBI items
(3, 'Tax-Exempt Organizations', 'Metro Community Services, a 501(c)(3), has $45,000 in unrelated business income and $60,000 in directly connected expenses for 2025, creating a $15,000 net operating loss from UBI activities. In 2026, Metro has $30,000 in unrelated business income and $10,000 in directly connected expenses. Metro also has $50,000 in losses from its exempt activities. Apply the NOL rules to calculate Metro''s 2026 unrelated business taxable income.', '["$20,000, because only exempt activity losses offset UBI", "$19,000, after the $1,000 specific deduction but before any NOL carryforward", "$5,000, after applying the $15,000 UBI NOL carryforward but before the specific deduction", "$4,000, after applying the $15,000 UBI NOL carryforward and the $1,000 specific deduction"]'::jsonb, 3, 'Under IRC Section 512(b)(6), NOLs for UBIT purposes are computed using only unrelated business income items. The 2025 UBI NOL of $15,000 carries forward. In 2026: $30,000 income minus $10,000 expenses = $20,000, minus $15,000 NOL carryforward = $5,000, minus $1,000 specific deduction = $4,000 UBTI. Option C is wrong because it omits the $1,000 specific deduction under Section 512(b)(12). Exempt activity losses cannot offset UBI.', 'medium', 3),

-- Q10: easy / L1 — Private inurement definition
(3, 'Tax-Exempt Organizations', 'Under Section 501(c)(3), what does the prohibition against private inurement mean?', '["No part of the organization''s net earnings may benefit any private shareholder or individual who is an insider", "The organization may not earn any profit from its activities", "The organization must distribute all income to the public each year", "The organization may not invest in stocks or bonds"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the private inurement prohibition prevents any part of an organization''s net earnings from benefiting private shareholders or individuals with a personal stake in the organization (insiders such as founders, officers, or directors). Option B is wrong because exempt organizations may earn profits — they simply cannot distribute those earnings to insiders for personal benefit.', 'easy', 1),

-- Q11: medium / L2 — Form 990-N (e-Postcard) threshold
(3, 'Tax-Exempt Organizations', 'Neighborhood Watch Alliance, a small 501(c)(3), has gross receipts of $38,000 and total assets of $120,000 for the current year. Which annual information return must the organization file with the IRS?', '["Form 990, because total assets exceed $100,000", "Form 990-EZ, because gross receipts are below $200,000", "Form 990-N (e-Postcard), because gross receipts are normally $50,000 or less", "No filing is required for organizations with gross receipts below $50,000"]'::jsonb, 2, 'Under IRC Section 6033, organizations with gross receipts normally $50,000 or less may file Form 990-N (e-Postcard), an electronic notice requiring only basic information such as name, address, and EIN. At $38,000 in gross receipts, Neighborhood Watch Alliance qualifies. Option B is wrong because Form 990-EZ is for organizations with gross receipts under $200,000 and total assets under $500,000 that exceed the 990-N threshold.', 'medium', 2),

-- Q12: easy / L1 — Section 4940 tax rate on net investment income
(3, 'Tax-Exempt Organizations', 'What is the excise tax rate imposed on a private foundation''s net investment income under Section 4940?', '["1.39%", "0.50%", "2.00%", "5.00%"]'::jsonb, 0, 'Under IRC Section 4940, private foundations pay an excise tax of 1.39% on net investment income, which includes interest, dividends, rents, royalties, and capital gains. This tax applies regardless of whether the foundation meets its minimum distribution requirements. Option C is wrong because the 2% rate was eliminated by the Taxpayer Certainty and Disaster Tax Relief Act, replacing it with the flat 1.39% rate.', 'easy', 1),

-- Q13: medium / L3 — Research exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Lakewood University, a 501(c)(3), conducts three research programs: (1) a $500,000 contract with the U.S. Department of Defense, (2) a $200,000 project funded by a private pharmaceutical company with results kept proprietary, and (3) a $300,000 study whose findings are freely published and available to the general public. Apply the research exclusion to determine which programs generate UBIT.', '["All three programs are excluded from UBIT because universities are exempt organizations", "Only Program 1 is excluded because it is government-funded", "Only Program 3 is excluded because public availability is the sole research exclusion criterion", "Programs 1 and 3 are excluded, but Program 2 is subject to UBIT because proprietary results do not qualify"]'::jsonb, 3, 'Under IRC Section 512(b)(8)-(9), research performed for the U.S. government or by a college/university is excluded from UBIT, as is research whose results are freely available to the public. Program 1 (government contract) and Program 3 (publicly available results) qualify for exclusions. Program 2''s proprietary results for a private company do not qualify. Option A is wrong because the research exclusion has specific criteria — not all university research is automatically excluded from UBIT.', 'medium', 3),

-- Q14: easy / L1 — Form 990-PF for private foundations
(3, 'Tax-Exempt Organizations', 'Which annual information return must all private foundations file regardless of their size or income level?', '["Form 990-PF", "Form 990", "Form 990-EZ", "Form 990-N"]'::jsonb, 0, 'Under IRC Section 6033, all private foundations must file Form 990-PF annually regardless of their gross receipts or total assets. This form includes detailed reporting on investments, grants, excise tax computations, and minimum distribution requirements. Option C is wrong because Form 990-EZ is a simplified return for smaller public charities and is not available to private foundations.', 'easy', 1),

-- Q15: easy / L1 — Dissolution clause definition
(3, 'Tax-Exempt Organizations', 'What is the dissolution clause required in the governing documents of a Section 501(c)(3) organization?', '["A provision limiting the organization''s lobbying activities to an insubstantial amount", "A provision requiring annual audits by an independent accounting firm", "A provision directing that assets be distributed to another exempt organization or the government upon dissolution", "A provision prohibiting compensation to officers and directors"]'::jsonb, 2, 'Under IRC Section 501(c)(3) and Treas. Reg. Section 1.501(c)(3)-1(b)(4), the organizational test requires a dissolution clause specifying that upon dissolution, remaining assets must be distributed to another 501(c)(3) organization or to a federal, state, or local government for a public purpose. Option A is wrong because lobbying limitations are part of the operational test, not the dissolution clause requirement.', 'easy', 1),

-- Q16: medium / L2 — Filing deadline for calendar-year exempt organization
(3, 'Tax-Exempt Organizations', 'Green Earth Initiative, a calendar-year 501(c)(3) public charity, needs to file its annual Form 990. The organization''s fiscal year ends December 31. By what date must Green Earth file its Form 990, assuming no extension is requested?', '["March 15 of the following year", "May 15 of the following year", "April 15 of the following year", "June 15 of the following year"]'::jsonb, 1, 'Under IRC Section 6072(e), the Form 990 filing deadline is the 15th day of the 5th month after the end of the organization''s tax year. For a calendar-year organization ending December 31, the deadline is May 15 of the following year. Extensions of up to 6 months are available using Form 8868. Option A is wrong because March 15 is the deadline for S corporation and partnership returns, not exempt organization returns.', 'medium', 2),

-- Q17: medium / L2 — One-third support test for public charity status
(3, 'Tax-Exempt Organizations', 'Sunrise Community Foundation received $400,000 in total support over its most recent four-year period. Of this amount, $180,000 came from government grants and small individual contributions (no single donor exceeding 2% of total support). The remaining $220,000 came from investment income and a single $150,000 gift from the founder''s family. Under the one-third support test of Section 509(a)(1), how is Sunrise classified?', '["Private foundation, because the founder''s family contribution exceeds one-third of total support", "Private foundation, because investment income cannot count toward public support", "Public charity, because it received at least $100,000 in government grants", "Public charity, because government and public support of $180,000 exceeds one-third of total support"]'::jsonb, 3, 'Under IRC Section 509(a)(1) and Section 170(b)(1)(A)(vi), an organization qualifies as a public charity if it normally receives at least one-third of its total support from governmental units and the general public. Sunrise received $180,000 in qualifying public support out of $400,000 total (45%), exceeding the one-third threshold. Option A is wrong because the test measures the ratio of public support to total support, not individual contribution size.', 'medium', 2),

-- Q18: easy / L1 — Form 990-T filing threshold
(3, 'Tax-Exempt Organizations', 'What is the minimum amount of gross unrelated business income that requires a tax-exempt organization to file Form 990-T?', '["$500", "$5,000", "$1,000", "$10,000"]'::jsonb, 2, 'Under IRC Section 6012(a)(6), a tax-exempt organization must file Form 990-T when it has $1,000 or more in gross unrelated business income. The $1,000 specific deduction under Section 512(b)(12) offsets the first $1,000 of net UBI but does not eliminate the filing requirement when gross income reaches this threshold. Option A is wrong because the filing threshold is $1,000, not $500.', 'easy', 1),

-- Q19: hard / L4 — Section 4945 grants to non-charities without expenditure responsibility
(3, 'Tax-Exempt Organizations', 'Parker Family Foundation, a private foundation, makes two grants: (1) a $100,000 grant to a 501(c)(4) social welfare organization for community development, without exercising expenditure responsibility, and (2) a $50,000 grant to a 501(c)(3) public charity for its homeless shelter program. Evaluate how Section 4945 treats each grant and determine the total taxable expenditure.', '["Both grants are taxable expenditures totaling $150,000 in penalized amounts", "Neither grant is a taxable expenditure because both recipients are tax-exempt", "The $100,000 grant to the 501(c)(4) is a taxable expenditure; the $50,000 grant to the public charity is not", "Both grants require expenditure responsibility, but only the $100,000 grant triggers the tax"]'::jsonb, 2, 'Under IRC Section 4945(d)(4), grants by a private foundation to non-501(c)(3) organizations are taxable expenditures unless the foundation exercises expenditure responsibility to ensure funds are used for charitable purposes. The $100,000 grant to a 501(c)(4) without expenditure responsibility is a taxable expenditure. Grants to 501(c)(3) public charities do not require expenditure responsibility. Option B is wrong because tax-exempt status alone does not exempt grants from Section 4945 — only grants to 501(c)(3) public charities avoid the requirement.', 'hard', 4),

-- Q20: medium / L3 — Bingo games exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Cedar Valley Volunteer Fire Department, a 501(c)(3), hosts weekly bingo nights at its fire station. The local municipality permits nonprofit bingo games, and no commercial bingo halls operate in the jurisdiction. The fire department uses paid staff to run the bingo operations. Apply the bingo exclusion to determine whether the bingo income is subject to UBIT.', '["The bingo income is excluded from UBIT because the games are legal and commercial bingo is not ordinarily carried on in the jurisdiction", "The bingo income is subject to UBIT because paid staff operate the games rather than volunteers", "The bingo income is excluded only if all workers are unpaid volunteers", "The bingo income is subject to UBIT because weekly bingo is a regularly carried on trade or business"]'::jsonb, 0, 'Under IRC Section 513(f), bingo games are excluded from UBIT if they are legal under state and local law and commercial bingo is not ordinarily carried on in the jurisdiction. Unlike the volunteer labor exclusion, the bingo exclusion does not require unpaid workers. Option B is wrong because the bingo exclusion applies regardless of whether employees or volunteers operate the games — it is a separate statutory exclusion from the volunteer labor exclusion.', 'medium', 3),

-- Q21: easy / L1 — Additional tax on uncorrected excess benefit under Section 4958
(3, 'Tax-Exempt Organizations', 'Under Section 4958, what is the additional excise tax imposed on a disqualified person who fails to correct an excess benefit transaction within the taxable period?', '["25% of the excess benefit", "200% of the excess benefit", "100% of the excess benefit", "50% of the excess benefit"]'::jsonb, 1, 'Under IRC Section 4958(b), if a disqualified person does not correct an excess benefit transaction within the taxable period, an additional excise tax of 200% of the excess benefit is imposed. This is in addition to the initial 25% tax. Option C is wrong because 100% is not the correct rate — the additional tax is specifically set at 200% to strongly incentivize prompt correction of excess benefit transactions.', 'easy', 1),

-- Q22: medium / L3 — Private benefit vs. private inurement distinction
(3, 'Tax-Exempt Organizations', 'Helping Hands Foundation, a 501(c)(3), hires an outside marketing consultant who is not an officer, director, or employee. The foundation pays the consultant $250,000 for services that comparable firms provide for $80,000. The consultant has no formal relationship with any insider. Analyze whether this arrangement violates the private inurement prohibition, the private benefit doctrine, or both.', '["This violates only the private inurement prohibition because the payment is excessive", "This violates both private inurement and private benefit because the payment exceeds fair value", "This violates only the private benefit doctrine because the consultant is not an insider", "This violates neither doctrine because the consultant provided legitimate services for the agreed-upon fee"]'::jsonb, 2, 'Under IRC Section 501(c)(3), private inurement applies only to insiders (private shareholders or individuals with a personal stake in the organization). Since the consultant is not an officer, director, or insider, private inurement does not apply. However, the private benefit doctrine is broader — it prohibits excessive benefits to any person, insider or not. The $170,000 overpayment constitutes impermissible private benefit. Option A is wrong because private inurement requires the beneficiary to be an insider.', 'medium', 3),

-- Q23: medium / L3 — Regularly carried on test (sporadic vs. year-round)
(3, 'Tax-Exempt Organizations', 'Eastside Youth Center, a 501(c)(3), operates a parking lot during eight home football games at a nearby university each fall, charging $20 per vehicle. The lot is otherwise used for the center''s recreational programs. The parking operation generates $48,000 in total revenue. Apply the regularly carried on test to determine whether this income is subject to UBIT.', '["The income is subject to UBIT because it meets all three parts of the UBIT test", "The income is not subject to UBIT because the parking lot activity is not regularly carried on", "The income is not subject to UBIT because parking lots always qualify for the convenience exclusion", "The income is subject to UBIT because $48,000 exceeds the $1,000 specific deduction"]'::jsonb, 1, 'Under IRC Section 512, an activity must be regularly carried on to trigger UBIT — meaning conducted with a frequency and continuity comparable to commercial operations. Operating a parking lot during only eight events per year is intermittent and seasonal, not comparable to a commercial parking lot''s year-round operations. Option A is wrong because the regularly carried on prong fails — the activity lacks the frequency and continuity required for UBIT to apply.', 'medium', 3),

-- Q24: easy / L1 — Section 4943 combined holding limit
(3, 'Tax-Exempt Organizations', 'Under Section 4943, what is the general maximum combined ownership of voting stock that a private foundation and its disqualified persons may hold in a for-profit corporation?', '["20%", "10%", "15%", "50%"]'::jsonb, 0, 'Under IRC Section 4943, the combined holdings of a private foundation and all disqualified persons generally may not exceed 20% of the voting stock of a business enterprise. Holdings above this threshold are considered excess business holdings subject to a 10% initial excise tax. Option D is wrong because 50% far exceeds the 20% general limit established by Section 4943 to prevent private foundations from controlling commercial enterprises.', 'easy', 1),

-- Q25: medium / L2 — Form 8868 extension for Form 990 filing
(3, 'Tax-Exempt Organizations', 'Pacific Arts Council, a calendar-year 501(c)(3), realizes on April 30 that it cannot complete its Form 990 by the May 15 filing deadline. The organization''s accountant files Form 8868 requesting an extension. What is the maximum length of extension available?', '["3 months, extending the deadline to August 15", "9 months, extending the deadline to February 15 of the following year", "12 months, extending the deadline to May 15 of the following year", "6 months, extending the deadline to November 15"]'::jsonb, 3, 'Under IRC Section 6081, Form 8868 provides an automatic extension of up to 6 months for filing Form 990. For a calendar-year organization with a May 15 deadline, this extends the filing date to November 15. The extension is automatic upon timely filing and does not require IRS approval. Option A is wrong because the available extension is 6 months, not 3 months.', 'medium', 2),

-- Q26: easy / L1 — Penalty for failure to file Form 990
(3, 'Tax-Exempt Organizations', 'What is the daily penalty for failure to timely file Form 990 for an exempt organization with gross receipts under $1,186,000?', '["$20 per day, up to the lesser of $10,500 or 5% of gross receipts", "$50 per day, up to $25,000", "$10 per day, up to $5,000", "$100 per day, up to $53,000"]'::jsonb, 0, 'Under IRC Section 6652(c)(1)(A), the penalty for failure to timely file Form 990 is $20 per day, up to the lesser of $10,500 or 5% of the organization''s gross receipts, for organizations with gross receipts under $1,186,000. For larger organizations, the penalty increases to $100 per day up to $53,000. Option D is wrong because the $100 per day penalty applies only to organizations with gross receipts of $1,186,000 or more.', 'easy', 1),

-- Q27: hard / L4 — Section 4945 taxable expenditures (private foundation lobbying)
(3, 'Tax-Exempt Organizations', 'Sterling Foundation, a private foundation, spends $75,000 on a campaign urging state legislators to increase education funding. The foundation''s counsel argues this is permissible because 501(c)(3) organizations may engage in insubstantial lobbying, and the amount is less than 5% of total expenditures. Evaluate the counsel''s position under Section 4945 and determine the applicable consequences.', '["The counsel is correct because the lobbying is insubstantial relative to total expenditures", "The $75,000 is a taxable expenditure subject to a 20% excise tax ($15,000) under Section 4945 because private foundations cannot engage in any lobbying", "The lobbying is permissible because private foundations may elect the Section 501(h) expenditure test", "The $75,000 is subject only to the 1.39% net investment income tax under Section 4940"]'::jsonb, 1, 'Under IRC Section 4945(d)(1), any amount paid by a private foundation to influence legislation is a taxable expenditure subject to a 20% excise tax on the foundation and a 5% tax on any manager who knowingly approved it. Unlike public charities, private foundations cannot engage in any lobbying — the "insubstantial part" test and the Section 501(h) election are unavailable to them. Option A is wrong because the insubstantial lobbying allowance applies only to public charities, not private foundations.', 'hard', 4),

-- Q28: medium / L2 — Automatic public charity classifications
(3, 'Tax-Exempt Organizations', 'Grace Community Church, a 501(c)(3) religious organization, receives 90% of its annual funding from a single wealthy donor family. Despite this concentrated funding source, Grace Community Church is classified as a public charity. Which rule explains this classification?', '["Churches are automatically classified as public charities under Section 170(b)(1)(A)(i) regardless of their funding sources", "Section 509(a)(1) one-third support test, because all religious donations count as public support", "Section 509(a)(3) supporting organization rules, because the church supports the donor family''s charitable intent", "Section 509(a)(2) gross receipts test, because religious donations qualify as exempt function gross receipts"]'::jsonb, 0, 'Under IRC Section 170(b)(1)(A)(i), churches are automatically classified as public charities regardless of their funding sources or support patterns. This automatic classification extends to schools and hospitals as well. Option C is wrong because supporting organization status under Section 509(a)(3) requires being organized to support another public charity, and the church is not organized to support the donor family.', 'medium', 2),

-- Q29: medium / L2 — Section 4958 initial tax on organization manager
(3, 'Tax-Exempt Organizations', 'Horizon Health Services, a 501(c)(3), enters into a compensation agreement paying its chief medical officer $1,800,000 per year. Comparable compensation at similar organizations is $600,000. The board chair knowingly approved the arrangement without reviewing comparability data. What excise tax applies to the board chair under Section 4958?', '["25% of the $1,200,000 excess benefit ($300,000)", "No tax, because only the disqualified person receiving the excess benefit is taxed", "5% of the $1,200,000 excess benefit ($60,000) with no cap", "10% of the $1,200,000 excess benefit, capped at $20,000 per transaction"]'::jsonb, 3, 'Under IRC Section 4958(a)(2), an organization manager who knowingly participates in an excess benefit transaction is subject to a 10% excise tax on the excess benefit, capped at $20,000 per transaction. Here, 10% of the $1,200,000 excess benefit equals $120,000, but the cap limits the manager''s tax to $20,000. Option A is wrong because the 25% initial tax applies to the disqualified person receiving the benefit, not to the organization manager.', 'medium', 2),

-- Q30: hard / L4 — Multiple private foundation excise taxes simultaneously
(3, 'Tax-Exempt Organizations', 'Wellington Family Foundation, a private foundation, had net investment income of $800,000 during the year. The foundation''s board (composed entirely of family members) approved purchasing the founder''s vacation home for $400,000 at appraised fair market value. The foundation also distributed only 3% of its $20,000,000 in non-charitable-use assets for charitable purposes instead of the required 5%. Evaluate which excise taxes under Sections 4940 through 4942 apply and calculate the combined initial tax liability.', '["Only the Section 4940 tax of $11,120 on net investment income applies", "Section 4940 tax of $11,120 plus Section 4941 self-dealing tax of $40,000 on the founder, totaling $51,120 on the two parties combined", "Section 4940 tax of $11,120, Section 4941 self-dealing tax of $40,000 on the founder, and Section 4942 tax of $120,000 on the undistributed amount", "Section 4941 self-dealing tax of $40,000 on the founder and Section 4942 tax of $120,000, but no Section 4940 tax"]'::jsonb, 2, 'Three excise taxes apply: (1) Section 4940 imposes 1.39% on $800,000 net investment income = $11,120. (2) Section 4941 imposes 10% on the self-dealer (founder) for the $400,000 purchase = $40,000, because any sale between a disqualified person and foundation is self-dealing regardless of FMV. (3) Section 4942 imposes 30% on the undistributed amount: 5% of $20M = $1,000,000 required minus $600,000 distributed = $400,000 shortfall times 30% = $120,000. Option A is wrong because it ignores both the self-dealing and underdistribution violations.', 'hard', 4)
;

COMMIT;
